tool_input.content:
import { chromium } from '@playwright/test'

const EXE = process.env.LOCALAPPDATA + '\\ms-playwright\\chromium-1243\\chrome-win64\\chrome.exe'
const browser = await chromium.launch({ executablePath: EXE })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true })
const page = await ctx.newPage()

const errors = []
page.on('pageerror', (e) => errors.push(e.message))

// 1) 进入应用：不应自动出现 vconsole
await page.goto('http://localhost:9000/#', { waitUntil: 'networkidle' })
await page.waitForTimeout(4000)
const onLaunch = await page.evaluate(() => ({
  instance: !!window.__vConsole,
  panel: !!document.querySelector('#__vconsole'),
}))

// 2) 进入客服中心，点头像 10 下应能唤起
await page.goto('http://localhost:9000/#/pages-my/customer/index', { waitUntil: 'networkidle' })
await page.waitForTimeout(3000)
const avatar = page.locator('img').first()
await avatar.waitFor({ state: 'visible', timeout: 20000 })

for (let i = 0; i < 10; i++) { await avatar.dispatchEvent('click'); await page.waitForTimeout(80) }
await page.waitForTimeout(3000)
const afterTap = await page.evaluate(() => ({
  instance: !!window.__vConsole,
  panel: !!document.querySelector('#__vconsole'),
}))

// 3) 再点 10 下关闭
for (let i = 0; i < 10; i++) { await avatar.dispatchEvent('click'); await page.waitForTimeout(80) }
await page.waitForTimeout(1500)
const afterClose = await page.evaluate(() => ({
  instance: !!window.__vConsole,
  panel: !!document.querySelector('#__vconsole'),
}))

console.log(JSON.stringify({ onLaunch, afterTap, afterClose, pageErrors: errors.length }, null, 2))
await browser.close()

